#[test]
fn test_resolution_refuses_what_the_catalogue_and_the_table_do_not_have() {
    let langs: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let engs: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let installed: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let out: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let msg: &mut String = &mut crate::port::new_text();
    en_cells1(engs, 99);
    crate::testport::assert_eq(en_resolve(pcls_macos(), 0, langs, engs, installed, out), pkerr_unknown_engine(), "an engine that is not in the table");
    crate::testport::assert_eq(crate::port::cells_at(out, 0), 99, "the subject");
    pk_explain(pkerr_unknown_engine(), out, msg);
    crate::testport::assert_text(msg, "unknown engine: 99", "named");
    en_cells1(engs, eng_pdfium());
    crate::testport::assert_eq(en_resolve(pcls_macos(), 0, langs, engs, installed, out), pkerr_not_ocr(), "a renderer does not read");
    en_cells1(engs, eng_apple_vision());
    crate::testport::assert_eq(en_resolve(pcls_windows(), 0, langs, engs, installed, out), pkerr_engine_class(), "Vision is not on Windows");
    let m2: &mut String = &mut crate::port::new_text();
    pk_explain(pkerr_engine_class(), out, m2);
    crate::testport::assert_text(m2, "engine is not available on the platform class: \"apple-vision\" on \"windows\"", "both named");
    crate::port::cells_drop(engs, 0);
    crate::testport::assert_eq(en_resolve(9, 0, langs, engs, installed, out), pkerr_unknown_class(), "a class that is not one");
    crate::testport::assert_eq(crate::port::cells_at(out, 0), 9, "the subject");
    en_cells1(installed, 99);
    crate::testport::assert_eq(en_resolve(pcls_macos(), 0, langs, engs, installed, out), pkerr_unknown_pack(), "an installed pack that is not in the catalogue");
    crate::testport::assert_eq(crate::port::cells_at(out, 0), 99, "the subject");
    crate::port::cells_drop(installed, 0);
    en_cells1(langs, 0);
    crate::testport::assert_eq(en_resolve(pcls_macos(), 0, langs, engs, installed, out), pkerr_bad_language(), "no language is 0");
}
