#[test]
fn test_names_are_refused_by_name() {
    en_engine_list(0, &crate::testport::text_blob(" tesseract , ppocr,ppocr-web ")[..], 3, eng_tesseract());
    en_engine_list(0, &crate::testport::text_blob("")[..], 0, 0);
    en_engine_list(0, &crate::testport::text_blob("ppocr-web")[..], 1, eng_ppocr_web());
    en_engine_refused(0, &crate::testport::text_blob("tesseract,paddle,ppocr")[..], 1, "unknown engine: \"paddle\"");
    en_engine_refused(0, &crate::testport::text_blob("vision")[..], 0, "unknown engine: \"vision\"");
    en_pack_refused(0, &crate::testport::text_blob("tess-osd,tess-fast-xyz")[..], "unknown pack: \"tess-fast-xyz\"");
    let out: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let msg: &mut String = &mut crate::port::new_text();
    let ok: &[u8] = &crate::testport::text_blob("tess-fast-eng,tess-osd,pp5-det-mobile")[..];
    crate::testport::assert_eq(pk_parse_packs(ok, 0, crate::port::blob_len(ok), out, msg), pkerr_ok(), "pack ids read");
    crate::testport::assert_eq(crate::port::cells_len(out), 3, "three");
    crate::testport::assert_eq(crate::port::cells_at(out, 0), pkid_tess_fast_eng(), "first");
    crate::testport::assert_eq(crate::port::cells_at(out, 1), pkid_tess_osd(), "second");
    crate::testport::assert_eq(crate::port::cells_at(out, 2), pkid_pp5_det_mobile(), "third");
}
