#[test]
fn test_the_record_of_an_engine_table_follows_the_table_and_refuses_what_it_does_not_have() {
    let avail: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let out: &mut crate::port::Cells = &mut crate::port::Cells::new();
    crate::port::cells_push(avail, eng_ppocr());
    crate::port::cells_push(avail, eng_tesseract());
    crate::port::cells_push(avail, eng_ppocr());
    crate::testport::assert_eq(pk_record_engines(out, pcls_macos(), avail), pkerr_ok(), "the engines of a hybrid run");
    crate::testport::assert_eq(crate::port::cells_len(out), 6, "two rows");
    crate::testport::assert_eq(crate::port::cells_at(out, 0), eng_tesseract(), "in the table's order, once each");
    crate::testport::assert_eq(crate::port::cells_at(out, 1), pk_engine_caps(eng_tesseract()), "the caps the table declares");
    crate::testport::assert_eq(crate::port::cells_at(out, 2), erole_incumbent(), "the role it takes by default");
    crate::testport::assert_eq(crate::port::cells_at(out, 3), eng_ppocr(), "second");
    crate::testport::assert_eq(crate::port::cells_at(out, 5), erole_challenger(), "the challenger");
    en_cells1(avail, eng_apple_vision());
    crate::testport::assert_eq(pk_record_engines(out, pcls_windows(), avail), pkerr_engine_class(), "an engine that cannot run on the class is not recorded");
    en_cells1(avail, 42);
    crate::testport::assert_eq(pk_record_engines(out, pcls_macos(), avail), pkerr_unknown_engine(), "nor one that is not in the table");
    crate::testport::assert_eq(crate::port::cells_at(out, 0), 42, "named");
    crate::port::cells_drop(avail, 0);
    crate::testport::assert_eq(pk_record_engines(out, pcls_macos(), avail), pkerr_ok(), "no engine at all");
    crate::testport::assert_eq(crate::port::cells_len(out), 0, "no rows");
    crate::testport::assert_eq(pk_record_engines(out, 0, avail), pkerr_unknown_class(), "no class");
}
pub(crate) fn en_prod(t: &mut crate::emon::transcriptctx::Tr) -> i32 {
    let k: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let v: &mut crate::port::Cells = &mut crate::port::Cells::new();
    crate::port::cells_push(k, 101);
    crate::port::cells_push(k, 110);
    crate::port::cells_push(k, 103);
    crate::port::cells_push(v, 116);
    crate::port::cells_push(v, 101);
    crate::port::cells_push(v, 115);
    crate::port::cells_push(v, 115);
    return tr_add_producer(t, k, v);
}
pub(crate) fn en_read_table(emon_t: i32) -> i32 {
    let b: &[u8] = &crate::testport::text_blob("{:emon-transcript 1\n :pk-engines [{:engine \"tesseract\" :caps 7339791 :role :incumbent} {:engine \"apple-vision\" :caps 1048992 :role :reader}]\n :producer {:eng \"tess\"}\n :inputs [{:index 0 :length 94562}]\n :entries []}\n")[..];
    let t: &mut crate::emon::transcriptctx::Tr = &mut crate::emon::transcriptctx::Tr::new();
    let out: &mut String = &mut crate::port::new_text();
    crate::testport::assert_eq(tr_read(t, b), 0, "a transcript with an engine table reads");
    crate::testport::assert_eq(tr_n_engines(t), 2, "two engines");
    crate::testport::assert_eq(tr_eng_engine(t, 0), eng_tesseract(), "the first");
    crate::testport::assert_eq(tr_eng_caps(t, 0), 7339791, "its caps");
    crate::testport::assert_eq(tr_eng_role(t, 0), erole_incumbent(), "its role");
    crate::testport::assert_eq(tr_eng_engine(t, 1), eng_apple_vision(), "the second");
    crate::testport::assert_eq(tr_eng_caps(t, 1), 1048992, "its caps");
    crate::testport::assert_eq(tr_eng_role(t, 1), erole_reader(), "an uncalibrated engine read alone");
    tr_write(t, out);
    crate::testport::assert_text(out, "{:emon-transcript 1\n :pk-engines [{:engine \"tesseract\" :caps 7339791 :role :incumbent} {:engine \"apple-vision\" :caps 1048992 :role :reader}]\n :producer {:eng \"tess\"}\n :inputs [{:index 0 :length 94562}]\n :entries []}\n", "read and written again, the same bytes");
    return 0;
}
pub(crate) fn en_read_none(emon_t: i32) -> i32 {
    let b: &[u8] = &crate::testport::text_blob("{:emon-transcript 1\n :inputs []\n :entries []}\n")[..];
    let t: &mut crate::emon::transcriptctx::Tr = &mut crate::emon::transcriptctx::Tr::new();
    let out: &mut String = &mut crate::port::new_text();
    crate::testport::assert_eq(tr_read(t, b), 0, "a transcript with none reads");
    crate::testport::assert_eq(tr_n_engines(t), 0, "no engines");
    tr_write(t, out);
    crate::testport::assert_text(out, "{:emon-transcript 1\n :inputs []\n :entries []}\n", "and writes none");
    return 0;
}
#[test]
fn test_the_engine_table_is_written_first_and_read_back() {
    let t: &mut crate::emon::transcriptctx::Tr = &mut crate::emon::transcriptctx::Tr::new();
    let out: &mut String = &mut crate::port::new_text();
    tr_add_engine(t, eng_tesseract(), 7339791, erole_incumbent());
    tr_add_engine(t, eng_ppocr(), 24928, erole_challenger());
    en_prod(t);
    tr_add_input(t, 0, 94562);
    tr_write(t, out);
    crate::testport::assert_text(out, "{:emon-transcript 1\n :pk-engines [{:engine \"tesseract\" :caps 7339791 :role :incumbent} {:engine \"ppocr\" :caps 24928 :role :challenger}]\n :producer {:eng \"tess\"}\n :inputs [{:index 0 :length 94562}]\n :entries []}\n", "the table comes before the producer, the inputs and the entries");
    en_read_table(0);
    en_read_none(0);
}
